from .exceptions import RfSwitchTypeNotSupported

_default = 'DEFAULT'


class RfSwitchTypes:
    def __init__(self, rf_switch_types):
        if isinstance(rf_switch_types, dict):
            self.available_types = rf_switch_types
        else:
            self.available_types = {_default: rf_switch_types}

    def __getitem__(self, item):
        try:
            if item:
                item = item.upper()
            else:
                item = _default
            rf_switch_type = self.available_types[item]
            return rf_switch_type
        except KeyError:
            raise RfSwitchTypeNotSupported(f'{item} is not supported')


